-- Generated by scripts/feature-post.mjs. Makes "auto-repair-declined-repairs-revisit-date" the featured Industry LoogoBlog
-- post. Clear first, then set, so posts_one_featured never sees two rows.
UPDATE "posts" SET "featured" = false WHERE "featured" AND "slug" <> 'auto-repair-declined-repairs-revisit-date';
UPDATE "posts" SET "featured" = true WHERE "slug" = 'auto-repair-declined-repairs-revisit-date' AND "status" = 'published';
